import { digest } from '../shared/digest';
import { grants } from './grant-store';

export class ReusedFamilyProof extends Error {}

export async function exchangeFamilyProof(familyId: string, presentedSecret: string) {
  const presented = digest(presentedSecret);
  const current = await grants.consumeCurrent(familyId, presented);
  if (!current) {
    await grants.revokeFamily(familyId);
    throw new ReusedFamilyProof('previously consumed family proof presented again');
  }
  const successor = await grants.issueSuccessor(familyId);
  return { access: current.accessGrant, renewal: successor.secret };
}

import { exchangeFamilyProof } from './credential-family';

export async function renewSession(request: Request) {
  const body = await request.json();
  return Response.json(await exchangeFamilyProof(body.family, body.proof));
}

import { verifyPassword } from './passwords';
import { grants } from './grant-store';

export async function login(email: string, password: string) {
  await verifyPassword(email, password);
  return grants.startFamily(email);
}

export const grants = {
  async startFamily(subject: string) { return { subject, family: crypto.randomUUID() }; },
  async consumeCurrent(family: string, digest: string) { return database.consume(family, digest); },
  async issueSuccessor(family: string) { return database.issue(family); },
  async revokeFamily(family: string) { return database.revoke(family); },
};
declare const database: any;
